### 1. `AgentSession` Unit Tests

```typescript
// No TUI, no terminal, just pure logic
describe("AgentSession", () => {
  let mockAgent: MockAgent;
  let mockSessionManager: MockSessionManager;
  let mockSettingsManager: MockSettingsManager;
  let session: AgentSession;

  beforeEach(() => {
    mockAgent = createMockAgent();
    mockSessionManager = createMockSessionManager();
    mockSettingsManager = createMockSettingsManager();
    session = new AgentSession({ 
      agent: mockAgent, 
      sessionManager: mockSessionManager,
      settingsManager: mockSettingsManager 
    });
  });

  describe("thinking level", () => {
    it("cycles through levels", () => {
      mockAgent.state.model = { reasoning: true };

      expect(session.cycleThinkingLevel()).toBe("minimal");
      expect(session.cycleThinkingLevel()).toBe("low");
      expect(session.cycleThinkingLevel()).toBe("medium");
      // ...
    });

    it("returns null when model doesn't support thinking", () => {
      mockAgent.state.model = { reasoning: false };
      expect(session.cycleThinkingLevel()).toBeNull();
    });

    it("persists to session and settings", () => {
      session.setThinkingLevel("high");
      expect(mockSessionManager.saveThinkingLevelChange).toHaveBeenCalledWith("high");
      expect(mockSettingsManager.setDefaultThinkingLevel).toHaveBeenCalledWith("high");
    });
  });

  describe("compaction", () => {
    it("auto-compacts when threshold exceeded", async () => {
      mockSettingsManager.getCompactionSettings.mockReturnValue({ enabled: true, threshold: 0.8 });
      // Setup agent state with high token usage...

      const result = await session.checkAutoCompaction();
      expect(result).not.toBeNull();
      expect(mockSessionManager.saveCompaction).toHaveBeenCalled();
    });
  });

  describe("model cycling", () => {
    it("cycles through scoped models with thinking levels", async () => {
      const scopedModels = [
        { model: modelA, thinkingLevel: "high" },
        { model: modelB, thinkingLevel: "off" },
      ];
      session = new AgentSession({ ..., scopedModels });

      const result = await session.cycleModel();
      expect(result.model).toBe(modelB);
      expect(result.thinkingLevel).toBe("off");
    });
  });

  describe("bash execution", () => {
    it("adds result to agent context", async () => {
      const result = await session.executeBash("echo hello");
      expect(mockAgent.appendMessage).toHaveBeenCalledWith(
        expect.objectContaining({ role: "bashExecution", command: "echo hello" })
      );
    });

    it("can be aborted", async () => {
      const promise = session.executeBash("sleep 10");
      session.abortBash();
      const result = await promise;
      expect(result.cancelled).toBe(true);
    });
  });
});
```

